// ===== Responsive nav toggle =====
const toggle = document.querySelector('.nav-toggle');
const collapsible = document.querySelector('.tabs');
if (toggle && collapsible) {
  toggle.addEventListener('click', () => {
    const open = collapsible.classList.toggle('open');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
}
document.querySelectorAll('.tabs a').forEach(a =>
  a.addEventListener('click', () => {
    collapsible?.classList.remove('open');
    toggle?.setAttribute('aria-expanded', 'false');
  })
);

// ===== Utilities =====
function d(s) { return new Date(s); } // “yyyy-mm-dd hh:mm”
function sameDay(a, b) { return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate(); }
function fmtDay(date) { return date.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' }); } // 29 March 2024 [10][6]
function escapeHTML(s) { return s.replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m])); } // [10]

