// ===== Render helpers for date-stamped grids =====
function insertDateSeparators(container, items, renderer) {
  container.innerHTML = '';
  const sorted = [...items].sort((a, b) => a.date - b.date); // chronological [4]
  let prev = null;
  sorted.forEach((item) => {
    if (!prev || !sameDay(prev, item.date)) {
      const sep = document.createElement('div');
      sep.className = 'grid-sep';
      sep.textContent = fmtDay(item.date);
      container.appendChild(sep);
      prev = item.date;
    }
    container.appendChild(renderer(item));
  });
}

function renderGalleryItem(item) {
  const fig = document.createElement('figure');
  fig.dataset.full = item.src;
  fig.innerHTML = `
    <img src="${item.src}" alt="${escapeHTML(item.title)}" loading="lazy" />
    <figcaption>${escapeHTML(item.title)}</figcaption>
  `;
  return fig;
}

function renderVideoItem(item) {
  const fig = document.createElement('figure');
  fig.dataset.video = item.video;
  fig.innerHTML = `
    <img src="${item.thumb}" alt="${escapeHTML(item.title)}" loading="lazy" />
    <figcaption>${escapeHTML(item.title)}</figcaption>
  `;
  return fig;
}

// Mount into DOM
const galleryGrid = document.getElementById('galleryGrid');
const videoGrid = document.getElementById('videoGrid');

insertDateSeparators(galleryGrid, galleryItems, renderGalleryItem); // [4][5]
insertDateSeparators(videoGrid, videoItems, renderVideoItem);       // [4][5]

// ===== Lightbox (images + videos) =====
function collectFigures() {
  const divaFigures = [...document.querySelectorAll('#divaGrid figure')];
  const imageFigures = [...document.querySelectorAll('#galleryGrid figure')];
  const videoFigures = [...document.querySelectorAll('#videoGrid figure')];
  return [...divaFigures, ...imageFigures, ...videoFigures];
}

let figures = collectFigures();

const lb = document.getElementById('lightbox');
const lbWrap = document.getElementById('lbMediaWrap');
const lbPrev = document.getElementById('lbPrev');
const lbNext = document.getElementById('lbNext');
const lbClose = document.getElementById('lbClose');

let currentIndex = 0;

function renderMediaFor(index) {
  const fig = figures[index];
  if (!fig) return;
  const videoSrc = fig?.dataset.video;
  lbWrap.innerHTML = '';
  if (videoSrc) {
    // inside renderMediaFor(index) when videoSrc exists:
    const vid = document.createElement('video');
    vid.src = videoSrc;
    vid.controls = true;
    vid.playsInline = true;   // important for iOS inline playback
    // vid.muted = true;      // only if you want to allow autoplay
    // vid.autoplay = true;   // only combined with muted, otherwise blocked
    vid.style.background = '#000';
    lbWrap.appendChild(vid);

  } else {
    const src = fig.dataset.full || fig.querySelector('img').src;
    const img = document.createElement('img');
    img.src = src; img.alt = 'Media preview';
    lbWrap.appendChild(img);
  }
}
function openAt(i) { currentIndex = i; renderMediaFor(currentIndex); lb.classList.add('open'); }
function showDelta(d) { currentIndex = (currentIndex + d + figures.length) % figures.length; renderMediaFor(currentIndex); }

// Delegate clicks from both grids
function delegateOpen(container) {
  container.addEventListener('click', (e) => {
    const fig = e.target.closest('figure');
    if (!fig) return;
    // recompute in case content changed
    figures = collectFigures();
    const i = figures.indexOf(fig);
    if (i > -1) openAt(i);
  });
}
delegateOpen(galleryGrid);
delegateOpen(videoGrid);

lbPrev.addEventListener('click', () => showDelta(-1));
lbNext.addEventListener('click', () => showDelta(1));
lbClose.addEventListener('click', () => lb.classList.remove('open'));
lb.addEventListener('click', (e) => { if (e.target === lb) lb.classList.remove('open'); });
document.addEventListener('keydown', (e) => {
  if (!lb.classList.contains('open')) return;
  if (e.key === 'Escape') lb.classList.remove('open');
  if (e.key === 'ArrowLeft') showDelta(-1);
  if (e.key === 'ArrowRight') showDelta(1);
}, { passive: true });

