function formatTime(date) { return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); } // [10]
function makeBubble({ who, text, time }) {
  const div = document.createElement('div');
  div.className = `bubble ${who}`;
  div.innerHTML = `${escapeHTML(text)}<span class="timestamp">${formatTime(time)}</span>`;
  return div;
}
function makeSeparator(date) {
  const sep = document.createElement('div');
  sep.className = 'sep';
  sep.textContent = fmtDay(date);
  return sep;
}
function renderChat() {
  msgs.innerHTML = '';
  const sorted = [...chatData].sort((a, b) => a.time - b.time);
  let prevDate = null;
  sorted.forEach((m) => {
    if (!prevDate || !sameDay(prevDate, m.time)) {
      msgs.appendChild(makeSeparator(m.time));
      prevDate = m.time;
    }
    msgs.appendChild(makeBubble(m));
  });
  msgs.scrollTop = msgs.scrollHeight;
}
renderChat();

chatForm?.addEventListener('submit', e => {
  e.preventDefault();
  const t = input.value.trim();
  if (!t) return;
  chatData.push({ who: 'me', text: t, time: new Date() });
  renderChat();
  input.value = '';
  setTimeout(() => { chatData.push({ who: 'friend', text: 'Noted 🌻', time: new Date() }); renderChat(); }, 600);
});

// Passive touch for smoother scrolling
document.addEventListener('touchstart', () => { }, { passive: true });

// ===== Background music with user-gesture start =====
// Autoplay with sound requires a gesture; start on first click/tap or on toggle press. [2][5][6][7]
const bgm = document.getElementById('bgm');
const musicToggle = document.getElementById('musicToggle');
const MUSIC_KEY = 'pd-music-on';

// Restore last state for this session (default on = true)
let wantsMusic = sessionStorage.getItem(MUSIC_KEY);
wantsMusic = wantsMusic === null ? 'true' : wantsMusic;

function updateToggleUI(isPlaying) {
  musicToggle.setAttribute('aria-pressed', isPlaying ? 'true' : 'false');
  musicToggle.textContent = isPlaying ? '🔊' : '🔈';
  musicToggle.setAttribute('aria-label', isPlaying ? 'Pause music' : 'Play music');
}

async function ensurePlay() {
  try {
    await bgm.play();
    updateToggleUI(true);
    sessionStorage.setItem(MUSIC_KEY, 'true');
  } catch (e) {
    // If play is blocked, keep toggle off; user can press again.
    updateToggleUI(false);
  }
}

function pauseMusic() {
  bgm.pause();
  updateToggleUI(false);
  sessionStorage.setItem(MUSIC_KEY, 'false');
}

musicToggle.addEventListener('click', async () => {
  if (bgm.paused) {
    await ensurePlay();
  } else {
    pauseMusic();
  }
});

// First user interaction anywhere should start music if desired
function firstGesture() {
  document.removeEventListener('click', firstGesture, { capture: true });
  document.removeEventListener('touchstart', firstGesture, { capture: true });
  if (wantsMusic === 'true') ensurePlay();
}
document.addEventListener('click', firstGesture, { capture: true, once: true });
document.addEventListener('touchstart', firstGesture, { capture: true, once: true });

// If user previously wanted it off, reflect that in UI
updateToggleUI(wantsMusic === 'true' && !bgm.paused);

const divaGrid = document.getElementById('divaGrid');

function delegateOpen(container) {
  container.addEventListener('click', (e) => {
    const fig = e.target.closest('figure');
    if (!fig) return;
    figures = collectFigures();
    const i = figures.indexOf(fig);
    if (i > -1) openAt(i);
  });
}

delegateOpen(divaGrid);      // add this line
delegateOpen(galleryGrid);
delegateOpen(videoGrid);

// ===== Sticky header polish =====
const header = document.querySelector('.site-header');
let lastY = 0;
function onScrollHeader() {
  const y = window.scrollY || document.documentElement.scrollTop;
  if (y > 8 && !header.classList.contains('scrolled')) header.classList.add('scrolled');
  else if (y <= 8 && header.classList.contains('scrolled')) header.classList.remove('scrolled');
  lastY = y;
}
window.addEventListener('scroll', onScrollHeader, { passive: true });
onScrollHeader();

// ===== Reveal on scroll (Intersection Observer) =====
// Mark elements you want to reveal by adding class="reveal" in HTML or programmatically below.
const revealEls = new Set();
// Helper to add element(s) to reveal registry
function registerReveal(selectorOrNodes) {
  const nodes = typeof selectorOrNodes === 'string' ? document.querySelectorAll(selectorOrNodes) : selectorOrNodes;
  nodes && [...nodes].forEach(n => { n.classList.add('reveal'); revealEls.add(n); });
}
// Observer
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-visible');
        io.unobserve(entry.target);
      }
    });
  }, { rootMargin: '0px 0px -10% 0px', threshold: 0.1 });
  // Observe current set after a microtask
  queueMicrotask(() => revealEls.forEach(el => io.observe(el)));
}

// Register key areas for reveal
registerReveal(['#hero .hero-inner', '.sec-head', '#galleryGrid figure', '#videoGrid figure', '#divaGrid figure', '.story-cta']);

// Stagger indices for gallery/video/diva items
function applyStagger(containerSelector) {
  const nodes = document.querySelectorAll(containerSelector + ' figure');
  nodes.forEach((n, i) => n.style.setProperty('--i', i.toString()));
}
applyStagger('#galleryGrid');
applyStagger('#videoGrid');
applyStagger('#divaGrid');

// If content is dynamically changed later, call registerReveal(...) and applyStagger(...) again.

// Optional: add reveal to date separators inside grids if present
registerReveal(document.querySelectorAll('.grid-sep'));

// ===== Lightbox: add opening animation toggle class already handled via CSS =====
// No JS changes needed; CSS targets .lightbox.open .frame for zoom-in.

// Auto-insert the small header image into every section header
document.querySelectorAll('.sec-head').forEach(head => {
  if (!head.querySelector('.sec-icon-img')) {
    const img = document.createElement('img');
    img.src = 'e.jpg';        // ensure e.jpg is next to index.html
    img.alt = '';
    img.setAttribute('aria-hidden', 'true');
    img.className = 'sec-icon-img';
    head.insertBefore(img, head.firstChild);
  }
});

