const divaGridEl = document.getElementById('divaGrid');
const divaPhotos = [
  'selected/20241122_135405.jpg', 'selected/20241206_163221.jpg', 'selected/20250312_145145.jpg', 'selected/20250425_153838.jpg', 'selected/20250425_154027.jpg',
  'selected/20250604_133946.jpg', 'selected/20250604_134435.jpg', 'selected/20250604_143951.jpg', 'selected/20250702_125730.jpg', 'selected/20250716_153839.jpg', 'selected/20250716_170000.jpg'
];

divaPhotos.forEach(name => {
  const src = `selected/${name}`;
  const fig = document.createElement('figure');
  fig.dataset.full = src;
  fig.innerHTML = `<img src="${src}" loading="lazy" />`;
  divaGridEl.appendChild(fig);
});

// Rebuild figure list so the lightbox includes these items
figures = collectFigures();
